#include <bitset>
#include <iostream>

int main() {
    std::bitset<8> b("11110000");

    b <<= 3; // Shift Left by 3
    // Three high bits discarded, three low bits zero-padded
    // Result: 10000000
    std::cout << "LShift: " << b << "\n"; 

    b >>= 7; // Shift Right by 7
    // Seven low bits discarded, seven high bits zero-padded
    // Result: 00000001
    std::cout << "RShift: " << b << "\n";

    b <<= 8; // Shift past size (clears)
    // Result: 00000000
    std::cout << "Clear:  " << b << "\n";
}
